settings.custom_liquid:
{%- liquid
  assign hero_image = 'https://cdn.shopify.com/s/files/1/0749/2377/0014/files/ChatGPT_Image_Sep_10_2026_09_45_33_PM_5d99003c-1631-4628-b07d-7a687b88284a.png?v=1789061400'
  assign hero_image_mobile = ''
  assign hero_alt = ''
  assign hero_heading = 'Practical Dog & Cat Supplies - Verified Sizing, Materials & Breed'
  assign hero_text = 'Shop 304 stainless steel water fountains, whisper-quiet LED nail grinders, interactive puzzle toys, escape-proof harnesses, and post-surgery recovery gear with exact measurements in inches and centimeters before you buy.'
  assign hero_btn_label = 'Shop Now'
  assign hero_btn_link = '/collections/all'
  assign hero_tag = 'h1'
  assign hero_align = 'left'
  assign hero_overlay = 1.0
-%}

<section class="hxc hxc--{{ hero_align }}">
  <picture class="hxc__media">
    {%- if hero_image_mobile != blank -%}
      <source media="(max-width: 749px)" srcset="{{ hero_image_mobile }}">
    {%- endif -%}
    <img
      class="hxc__img"
      src="{{ hero_image }}"
      alt="{{ hero_alt | escape }}"
      {%- if hero_alt == blank %} role="presentation"{% endif %}
      loading="eager"
      fetchpriority="high"
      decoding="async"
    >
  </picture>
  <div class="hxc__overlay" aria-hidden="true"></div>

  <div class="hxc__wrap page-width">
    <div class="hxc__content">
      <{{ hero_tag }} class="hxc__heading">{{ hero_heading | escape }}</{{ hero_tag }}>
      <p class="hxc__text">{{ hero_text | escape }}</p>
      <a href="{{ hero_btn_link }}" class="hxc__btn">{{ hero_btn_label | escape }}</a>
    </div>
  </div>
</section>

<style>
  .hxc {
    --hxc-text: #ffffff;
    --hxc-btn-bg: #ffffff;
    --hxc-btn-text: #000000;
    --hxc-overlay: {{ hero_overlay }};
    position: relative;
    display: flex;
    align-items: center;
    isolation: isolate;
    overflow: hidden;
    min-height: 70vh;
    padding: 72px 0;
    color: var(--hxc-text);
    background-color: #111;
  }
  .hxc__media, .hxc__overlay { position: absolute; inset: 0; }
  .hxc__media { z-index: 0; }

  /* Mobile: strong uniform dark overlay so text is readable over any part of the image */
  .hxc__overlay {
    z-index: 1;
    background: rgba(0,0,0,var(--hxc-overlay));
  }
  .hxc__img { display: block; 
    opacity: 50% !important;
width: 100%; height: 100%; object-fit: cover; object-position: center; }

  .hxc__wrap { position: relative; z-index: 2; width: 100%; display: flex; }
  .hxc--left .hxc__wrap { justify-content: flex-start; text-align: left; }
  .hxc--center .hxc__wrap { justify-content: center; text-align: center; }
  .hxc--right .hxc__wrap { justify-content: flex-end; text-align: right; }
  .hxc__content { width: 100%; max-width: 62rem; min-width: 0; }

  .hxc__heading {
    margin: 0;
    font-family: var(--font-heading-family);
    font-style: var(--font-heading-style);
    font-weight: var(--font-heading-weight);
    font-size: calc(var(--font-heading-scale, 1) * clamp(3rem, 8vw, 4.6rem));
    line-height: 1.12;
    color: #fff;
    overflow-wrap: break-word;
    text-wrap: balance;
    text-shadow: 0 2px 14px rgba(0,0,0,.6);
  }
  .hxc__text {
    margin: 1.6rem 0 0;
    max-width: 52rem;
    font-family: var(--font-body-family);
    font-style: var(--font-body-style);
    font-weight: var(--font-body-weight);
    font-size: calc(var(--font-body-scale, 1) * 1.6rem);
    line-height: 1.6;
    color: #fff;
    text-shadow: 0 1px 10px rgba(0,0,0,.6);
  }
  .hxc--center .hxc__text { margin-left: auto; margin-right: auto; }
  .hxc--right .hxc__text { margin-left: auto; }

  .hxc__btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 4.8rem;
    margin-top: 2.8rem;
    padding: 1.2rem 3.2rem;
    font-family: var(--font-body-family);
    font-style: var(--font-body-style);
    font-weight: var(--font-body-weight);
    font-size: calc(var(--font-body-scale, 1) * 1.5rem);
    line-height: 1.2;
    letter-spacing: .06rem;
    text-decoration: none;
    color: var(--hxc-btn-text);
    background-color: var(--hxc-btn-bg);
    border: max(var(--buttons-border-width, 1px), 1px) solid var(--hxc-btn-bg);
    border-radius: var(--buttons-radius, 0);
    transition: background-color .2s ease, color .2s ease;
  }
  .hxc__btn:hover { color: var(--hxc-btn-bg); background-color: transparent; }
  .hxc__btn:focus-visible { outline: .2rem solid var(--hxc-btn-bg); outline-offset: .3rem; }

  @media screen and (max-width: 749px) {
    .hxc__btn { width: 100%; }
    .hxc--center .hxc__btn { width: auto; min-width: 70%; }
  }
  @media screen and (min-width: 750px) {
    .hxc { min-height: 80vh; padding: 130px 0; }
    /* Desktop: darkest on the text side, lighter on the right so the image still shows */
    .hxc__overlay {
      background: linear-gradient(90deg, rgba(0,0,0,calc(var(--hxc-overlay) + .15)) 0%, rgba(0,0,0,var(--hxc-overlay)) 50%, rgba(0,0,0,calc(var(--hxc-overlay) * .5)) 100%);
    }
    .hxc__heading { font-size: calc(var(--font-heading-scale, 1) * clamp(4.2rem, 5vw, 6rem)); }
    .hxc__text { font-size: calc(var(--font-body-scale, 1) * 1.8rem); }
  }
  @media (prefers-reduced-motion: reduce) { .hxc__btn { transition: none; } }
</style>
